   213|          `Model: ${data.model_used} · kategori: ${cat || 'general'} · Arsify OS routing`;
   214|      }
   215|    } else {
   216|      addMsg('ai', `<span style="color:var(--amber)">Maaf, ada kesalahan (HTTP ${r.status}). Coba lagi.</span>`);
   217|    }
   218|  } catch (err) {
