   220|    addMsg('ai', `<span style="color:var(--amber)">Tidak dapat terhubung ke Arsify OS. Pastikan server berjalan.</span>`);
   221|  }
   222|
   223|  isTyping = false;
   224|  document.getElementById('sendBtn').disabled = false;
   225|  document.getElementById('inputBox').focus();
   226|}
   227|
