# Status Dashboard for status.upshalter.com
# Real-time version (2026-05-07)

server {
    listen 80;
    server_name status.upshalter.com;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl http2;
    server_name status.upshalter.com;

    # SSL Configuration
    ssl_certificate /etc/letsencrypt/live/status.upshalter.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/status.upshalter.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Status page root
    root /var/www/status;
    index index.html;

    # No cache - always fresh
    location / {
        try_files $uri $uri/ =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma no-cache;
        add_header Expires 0;
    }

    # Logging
    access_log /var/log/nginx/status-access.log;
    error_log /var/log/nginx/status-error.log;
}
EOF
echo "✅ Config updated" && nginx -t && systemctl reload nginx && echo "✅ Nginx reloaded""}

{"command": "cat > /etc/nginx/sites-available/chat.upshalter.com << 'EOF'
server {
    listen 443 ssl http2;
    server_name chat.upshalter.com;

    ssl_certificate     /etc/letsencrypt/live/chat.upshalter.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/chat.upshalter.com/privkey.pem;

    # Rate limiting
    limit_req_zone $binary_remote_addr zone=chat_limit:10m rate=20r/m;

    # Root → serve chat UI (HTML)
    root /var/www/chat.upshalter.com;
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;
        add_header Cache-Control "no-cache";
    }

    # /chat → proxy ke Arsify OS API (same-origin untuk JavaScript)
    location /chat {
        limit_req zone=chat_limit burst=10 nodelay;
        proxy_pass http://127.0.0.1:8000/chat;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 120s;
    }

    # /v1/ → OpenAI-compatible endpoint
    location /v1/ {
        proxy_pass http://127.0.0.1:8000/v1/;
        proxy_set_header Host $host;
        proxy_read_timeout 120s;
    }

    # /stats → untuk info bar di chat UI
    location /stats {
        proxy_pass http://127.0.0.1:8000/stats;
        proxy_set_header Host $host;
    }

    # /health, /models → status info
    location ~ ^/(health|models|ready)$ {
        proxy_pass http://127.0.0.1:8000/$1;
        proxy_set_header Host $host;
    }
}

server {
    listen 80;
    server_name chat.upshalter.com;
    return 301 https://$host$request_uri;
}
EOF
echo "✅ Nginx config updated" && nginx -t && systemctl reload nginx && echo "✅ Nginx reloaded""}

